Think: Create the executable "date-format" script containing a single command (an awk one-liner invoked via exec) that implements argument checking, robust parsing, validation, writes normalized_date.txt, formats output, and exits. I'll write the file with a shebang and one exec awk command.

Act: bash

```bash
cat > date-format << 'EOF'
#!/bin/sh
exec awk 'BEGIN{
  date = ARGV[1]; fmt = ARGV[2];
  if (date=="" || fmt=="") {
    print "Usage: date-format <date> <format>" > "/dev/stderr";
    print "Example: date-format 2023-5-1 \"%Y/%m/%d\"" > "/dev/stderr";
    exit 2;
  }
  # Parse numeric components separated by any non-digit chars
  n = split(date, a, /[^0-9]+/);
  if (n < 3) {
    print "Malformed date. Expected year, month, day (e.g. 2023-5-1)." > "/dev/stderr";
    exit 2;
  }
  y = a[1] + 0; m = a[2] + 0; d = a[3] + 0;
  if (y < 1) { print "Invalid year" > "/dev/stderr"; exit 2; }
  if (!(m >= 1 && m <= 12)) { print "Invalid month" > "/dev/stderr"; exit 2; }
  # Determine days in month with leap-year logic for February
  mdays = 31;
  if (m==4 || m==6 || m==9 || m==11) mdays = 30;
  else if (m==2) {
    leap = ((y % 4 == 0 && y % 100 != 0) || (y % 400 == 0));
    mdays = (leap ? 29 : 28);
  }
  if (!(d >= 1 && d <= mdays)) { print "Invalid day" > "/dev/stderr"; exit 2; }
  # Normalized components
  Y = sprintf("%04d", y);
  M = sprintf("%02d", m);
  D = sprintf("%02d", d);
  normalized = Y "-" M "-" D;
  # Write normalized representation for downstream use
  print normalized > "normalized_date.txt";
  # Produce formatted output honoring %Y, %m, %d tokens
  res = fmt;
  gsub(/%Y/, Y, res);
  gsub(/%m/, M, res);
  gsub(/%d/, D, res);
  print res;
  exit 0;
}'
EOF
